process DIAMOND_BLASTP {
    tag "${meta.id}.${meta2.id}"
    label 'process_high'

    conda "${moduleDir}/environment.yml"
    container "${workflow.containerEngine in ['singularity', 'apptainer'] && !task.ext.singularity_pull_docker_container
        ? 'https://depot.galaxyproject.org/singularity/diamond:2.2.1--he361c42_0'
        : 'quay.io/biocontainers/diamond:2.2.1--he361c42_0'}"

    input:
    tuple val(meta), path(fasta)
    tuple val(meta2), path(db)
    val outfmt
    val blast_columns

    output:
    tuple val(meta), path('*.{blast,blast.gz}'), optional: true, emit: blast
    tuple val(meta), path('*.{xml,xml.gz}'), optional: true, emit: xml
    tuple val(meta), path('*.{txt,txt.gz}'), optional: true, emit: txt
    tuple val(meta), path('*.{daa,daa.gz}'), optional: true, emit: daa
    tuple val(meta), path('*.{sam,sam.gz}'), optional: true, emit: sam
    tuple val(meta), path('*.{tsv,tsv.gz}'), optional: true, emit: tsv
    tuple val(meta), path('*.{paf,paf.gz}'), optional: true, emit: paf
    tuple val("${task.process}"), val('diamond'), eval('diamond --version 2>&1 | tail -n 1 | sed "s/^diamond version //"'), emit: versions_diamond, topic: versions

    when:
    task.ext.when == null || task.ext.when

    script:
    meta = meta + [ db: meta2.id ]

    def args = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}.${meta2.id}"

    def columns = blast_columns ? "${blast_columns}" : ''
    def out_ext = ""

    if (outfmt == 0) {
        out_ext = "blast"
    }
    else if (outfmt == 5) {
        out_ext = "xml"
    }
    else if (outfmt == 6) {
        out_ext = "txt"
    }
    else if (outfmt == 100) {
        out_ext = "daa"
    }
    else if (outfmt == 101) {
        out_ext = "sam"
    }
    else if (outfmt == 102) {
        out_ext = "tsv"
    }
    else if (outfmt == 103) {
        out_ext = "paf"
    }
    else {
        log.warn("Unknown output file format provided (${outfmt}): selecting DIAMOND default of tabular BLAST output (txt)")
        outfmt = 6
        out_ext = 'txt'
    }

    if (args =~ /--compress\s+1/) {
        out_ext += '.gz'
    }

    """
    diamond \\
        blastp \\
        --threads ${task.cpus} \\
        --db ${db} \\
        --query ${fasta} \\
        --outfmt ${outfmt} ${columns} \\
        ${args} \\
        --out ${prefix}.${out_ext}
    """

    stub:
    meta = meta + [ db: meta2.id ]

    def args = task.ext.args ?: ''
    def prefix = task.ext.prefix ?: "${meta.id}"

    def out_ext = ""

    if (outfmt == 0) {
        out_ext = "blast"
    }
    else if (outfmt == 5) {
        out_ext = "xml"
    }
    else if (outfmt == 6) {
        out_ext = "txt"
    }
    else if (outfmt == 100) {
        out_ext = "daa"
    }
    else if (outfmt == 101) {
        out_ext = "sam"
    }
    else if (outfmt == 102) {
        out_ext = "tsv"
    }
    else if (outfmt == 103) {
        out_ext = "paf"
    }
    else {
        log.warn("Unknown output file format provided (${outfmt}): selecting DIAMOND default of tabular BLAST output (txt)")
        outfmt = 6
        out_ext = 'txt'
    }

    if (args =~ /--compress\s+1/) {
        out_ext += '.gz'
    }

    """
    touch ${prefix}.${out_ext}
    """
}

nextflow_process {

    name "Test Process DIAMOND_BLASTP"
    script "../main.nf"
    process "DIAMOND_BLASTP"
    tag "modules"
    tag "modules_nfcore"
    tag "diamond"
    tag "diamond/makedb"
    tag "diamond/blastp"

    setup {
        run("DIAMOND_MAKEDB", alias: "FIRST_DB") {
            script "../../makedb/main.nf"
            process {
                """
                input[0] = [ [id:'db1'], [ file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ] ]
                input[1] = []
                input[2] = []
                input[3] = []
                """
            }
        }
    }

    test("sarscov2 - proteome - txt") {

        when {
            process {
                """
                input[0] = [ [id:'txt'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ]
                input[1] = FIRST_DB.out.db
                input[2] = 6
                input[3] = 'qseqid qlen'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }

    }

    test("sarscov2 - proteome - gz - txt") {

        when {
            process {
                """
                input[0] = [ [id:'txt.gz'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ]
                input[1] = FIRST_DB.out.db
                input[2] = 6
                input[3] = 'qseqid qlen'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match("gz_txt")}
            )
        }

    }

    test("sarscov2 - proteome - daa") {

        when {
            process {
                """
                input[0] = [ [id:'daa'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = FIRST_DB.out.db
                input[2] = 100
                input[3] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert process.out.daa },
                { assert snapshot(process.out.versions).match("daa") }
            )
        }

    }

    test("sarscov2 - proteome - txt - gz") {

        config "./nextflow.config"

        when {
            process {
                """
                input[0] = [ [id:'txt.gz'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = FIRST_DB.out.db
                input[2] = 6
                input[3] = 'qseqid qlen'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match("txt_gz") }
            )
        }

    }

    test("sarscov2 - proteome - double fasta/double db input") {

        when {
            run("DIAMOND_MAKEDB", alias: "SECOND_DB") {
                script "../../makedb/main.nf"
                process {
                    """
                    input[0] = [ [id:'db2'], [ file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome_test.faa', checkIfExists: true) ] ]
                    input[1] = []
                    input[2] = []
                    input[3] = []
                    """
                }
            }

            process {
                """
                input[0] = channel.of(
                    [ [id:'fasta1'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ],
                    [ [id:'fasta1'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta.gz', checkIfExists: true) ],
                    [ [id:'fasta2'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome_test.faa', checkIfExists: true) ],
                    [ [id:'fasta2'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome_test.faa', checkIfExists: true) ]
                )
                input[1] = FIRST_DB.out.db.concat(SECOND_DB.out.db).concat(FIRST_DB.out.db).concat(SECOND_DB.out.db)
                input[2] = 6
                input[3] = []
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out.toSorted()).match() }
            )
        }

    }

    test("sarscov2 - proteome - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = [ [id:'stub'], file(params.modules_testdata_base_path + 'genomics/sarscov2/genome/proteome.fasta', checkIfExists: true) ]
                input[1] = FIRST_DB.out.db
                input[2] = 6
                input[3] = 'qseqid qlen'
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match("stub") }
            )
        }

    }

}
